typedef float metric_t ;
typedef struct Row {
int id ;
metric_t value ;
char label [ 32 ] ;
}
Row ;
typedef struct Summary {
double average ;
double deviation ;
double rounded ;
}
Summary ;
extern _Atomic size_t records_loaded ;
int load_rows ( FILE * input , Row * * output , size_t * count ) ;
int compare_rows ( const void * a , const void * b ) ;
Summary summarize ( const Row * rows , size_t count ) ;
int write_report ( FILE * output , const Row * rows , size_t count , const Summary * summary ) ;
void on_exit_report ( void ) ;
int main ( int argc , char * * argv ) {
FILE * input = argc > 1 ? fopen ( argv [ 1 ] , "r" ) : stdin ;
if ( input == ( ( void * ) 0 ) ) {
perror ( "input" ) ;
return 1 ;
}
Row * rows = ( ( void * ) 0 ) ;
size_t count = 0 ;
if ( load_rows ( input , & rows , & count ) != 0 ) {
if ( input != stdin ) fclose ( input ) ;
return 1 ;
}
if ( input != stdin ) fclose ( input ) ;
atexit ( on_exit_report ) ;
qsort ( rows , count , sizeof * rows , compare_rows ) ;
Summary summary = summarize ( rows , count ) ;
int status = write_report ( stdout , rows , count , & summary ) ;
free ( rows ) ;
return status == 0 ? 0 : 1 ;
}

