if ( rows == ( ( void * ) 0 ) ) return - 1 ;
while ( fgets ( line , sizeof line , input ) != ( ( void * ) 0 ) ) {
int id , consumed ;
double raw ;
char label [ 32 ] ;
++ parse_calls ;
if ( sscanf ( line , "%d,%lf,%31[^\n]%n" , & id , & raw , label , & consumed ) != 3 ) {
++ parse_errors ;
continue ;
}
if ( used == capacity ) {
capacity *= 2 ;
Row * grown = realloc ( rows , capacity * sizeof * rows ) ;
if ( grown == ( ( void * ) 0 ) ) {
free ( rows ) ;
return - 1 ;
}
rows = grown ;
}
rows [ used ] . id = id ;
rows [ used ] . value = ( metric_t ) raw ;
memcpy ( rows [ used ] . label , label , strlen ( label ) + 1 ) ;
++ used ;
