int write_report ( FILE * output , const Row * rows , size_t count , const Summary * summary ) ;
void on_exit_report ( void ) ;
static void message ( FILE * stream , const char * format , ... ) {
va_list args ;
__builtin_va_start ( args , format ) ;
vfprintf ( stream , format , args ) ;
__builtin_va_end ( args ) ;
}
int write_report ( FILE * output , const Row * rows , size_t count , const Summary * summary ) {
int written = 0 ;
time_t now = time ( ( ( void * ) 0 ) ) ;
fprintf ( output , "%zu rows; mean=%.*f; deviation=%.3f%n\n" , count , 3 , summary -> average , summary -> deviation , & written ) ;
for ( size_t i = 0 ; i < count ; ++ i ) {
fprintf ( output , "%" "d" ",%s\n" , ( int32_t ) rows [ i ] . id , rows [ i ] . label ) ;
}
message ( output , "offset=%zu; time=%ld\n" , __builtin_offsetof ( Row , value ) , ( long ) now ) ;
size_t loaded = __c11_atomic_load ( & records_loaded , memory_order_relaxed ) ;
return written >= 0 && loaded >= count ? 0 : - 1 ;
}
void on_exit_report ( void ) {
}

