}
message ( output , "offset=%zu; time=%ld\n" , __builtin_offsetof ( Row , value ) , ( long ) now ) ;
size_t loaded = __c11_atomic_load ( & records_loaded , memory_order_relaxed ) ;
return written >= 0 && loaded >= count ? 0 : - 1 ;
