void requests(const char **src, size_t count, mbstate_t *state, wchar_t *out) {
    time_t now = time(NULL);
    fflush(NULL);
    size_t required = mbsrtowcs(NULL, src, count, state);
    size_t reset = mbrtowc(out, NULL, count, state);
    (void)now; (void)required; (void)reset;
}

